(6523430, 969949, 59695, '<td valign="top">A nice image, not one that overly excites me, but well executed, I am wondering if there are better compositions going in close, as there is a lot going on foliage wise with the blurred leaves creating distraction from the water. I do like the overall general composition though with the flow of the water cutting all the thirds well and causing a pleasant flow through the image (no pun intended)</td>', 'A nice image, not one that overly excites me, but well executed, I am wondering if there are better compositions going in close, as there is a lot going on foliage wise with the blurred leaves creating distraction from the water. I do like the overall general composition though with the flow of the water cutting all the thirds well and causing a pleasant flow through the image (no pun intended)', '2011-09-01 14:57:00.000000', NULL, 1),
(6523432, 970276, 59695, '<td valign="top">I like the comp of the white house, shame about the rain spots, tricky to avoid I guess. The shade of blue of sky is very dramatic though with a nice lightening capture (very jealous as I never have got lucky with one yet!)</td>', 'I like the comp of the white house, shame about the rain spots, tricky to avoid I guess. The shade of blue of sky is very dramatic though with a nice lightening capture (very jealous as I never have got lucky with one yet!)', '2011-09-01 14:58:57.000000', NULL, 1),
(6523434, 970204, 59695, '<td valign="top">Great colours, I might have been tempted to crop some of black sky to make a more of a letterbox crop as it doesn''t add anything in my opinion. The sharpness of the image is stunning and love the starlights on the bridge</td>', 'Great colours, I might have been tempted to crop some of black sky to make a more of a letterbox crop as it doesn''t add anything in my opinion. The sharpness of the image is stunning and love the starlights on the bridge', '2011-09-01 15:00:50.000000', NULL, 1),
(6523435, 970213, 59695, '<td valign="top">A classic shot, B&amp;W good choice, I might have been tempted to crop the tree out as the dark shape on the edge (against a predominently subdued image) of the frame keeps dragging my eye away from the bridge that I suspect you want to be the main subject</td>', 'A classic shot, B&W good choice, I might have been tempted to crop the tree out as the dark shape on the edge (against a predominently subdued image) of the frame keeps dragging my eye away from the bridge that I suspect you want to be the main subject', '2011-09-01 15:03:27.000000', NULL, 1),
(6523437, 970266, 59695, '<td valign="top">Interesting image, the only thing that bothers me is that the trees in the middle being a very dominent black that seperates this into two images. I might have been tempted to take another shot that exposes for the middle image and use that in conjunction with the submitted image t make it less of a dominant feature. I might also have been tempted to crop out the shadow on the grass as that too, for me, causes a distraction in the bright area at the bottom. The exposure of the sky and road are super though.</td>', 'Interesting image, the only thing that bothers me is that the trees in the middle being a very dominent black that seperates this into two images. I might have been tempted to take another shot that exposes for the middle image and use that in conjunction with the submitted image t make it less of a dominant feature. I might also have been tempted to crop out the shadow on the grass as that too, for me, causes a distraction in the bright area at the bottom. The exposure of the sky and road are super though.', '2011-09-01 15:08:16.000000', NULL, 1),
(6523440, 970089, 59695, '<td valign="top">I am not a huge fan of HDR, but here it works well, I might have been tempted to tone down the red sign and red lights on the top edge as against the generally muted tones keeps dragging my eye away from the glorious water and bridge</td>', 'I am not a huge fan of HDR, but here it works well, I might have been tempted to tone down the red sign and red lights on the top edge as against the generally muted tones keeps dragging my eye away from the glorious water and bridge', '2011-09-01 15:11:49.000000', NULL, 1),
(6523445, 969773, 59695, '<td valign="top">Well exposed, nice framing, quite busy, but not alot you can do there. I think the patterns in the wheel are very interesting</td>', 'Well exposed, nice framing, quite busy, but not alot you can do there. I think the patterns in the wheel are very interesting', '2011-09-01 15:15:03.000000', NULL, 1),
(6523448, 969979, 59695, '<td valign="top">Love the colour of the sky and the contrasting rocks, the little bit of light foliage at the bottom edge I find distracting and would have been tempted to crop out or burn in.</td>', 'Love the colour of the sky and the contrasting rocks, the little bit of light foliage at the bottom edge I find distracting and would have been tempted to crop out or burn in.', '2011-09-01 15:16:31.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6523452, 969885, 59695, '<td valign="top">Well executed shot, i like the framing of the trees on the right as a ''stopper'', the mountain well placed, would look great in a magazine, not as artistically stimulating as other images, but is in my top 5 images from this comp</td>', 'Well executed shot, i like the framing of the trees on the right as a ''stopper'', the mountain well placed, would look great in a magazine, not as artistically stimulating as other images, but is in my top 5 images from this comp', '2011-09-01 15:21:31.000000', NULL, 1),
(6523454, 970060, 59695, '<td valign="top">Good solid classic image, well executed. I might have been tempted either to crop the far right hand building or move the camera slightly to get it all - probably the latter.</td>', 'Good solid classic image, well executed. I might have been tempted either to crop the far right hand building or move the camera slightly to get it all - probably the latter.', '2011-09-01 15:23:01.000000', NULL, 1),
(6523455, 970274, 59695, '<td valign="top">I like the idea, there are others slightly better executed, mainly because of the extra effort around costumes to improve mood and drama</td>', 'I like the idea, there are others slightly better executed, mainly because of the extra effort around costumes to improve mood and drama', '2011-09-01 15:24:03.000000', NULL, 1),
(6523459, 969702, 59695, '<td valign="top">Very Bela Lugosi, good to see a different approach and ideas executed</td>', 'Very Bela Lugosi, good to see a different approach and ideas executed', '2011-09-01 15:24:36.000000', NULL, 1),
(6523460, 969649, 59695, '<td valign="top">A classic well executed shot, personally not overly stimulating artistically, but a good solid image all the same</td>', 'A classic well executed shot, personally not overly stimulating artistically, but a good solid image all the same', '2011-09-01 15:26:04.000000', NULL, 1),
(6523463, 970259, 59695, '<td valign="top">Interestng image, something a bit different from the crowd, I might have been tempted to burn in the top part of the image a bit, it is very over powering against the biker and bike so my eye keeps going up to it. The chromework in the darker areas looks great though</td>', 'Interestng image, something a bit different from the crowd, I might have been tempted to burn in the top part of the image a bit, it is very over powering against the biker and bike so my eye keeps going up to it. The chromework in the darker areas looks great though', '2011-09-01 15:28:40.000000', NULL, 1),
(6523466, 970268, 59695, '<td valign="top">Two people spotted the same scene! I love the glowing bush. The only personal niggle are the green and yellow lights on the left. I think I would have either cropped them out a bit and burned them in or just burned them in. They are the brightest items in the image and I keep getting distracted by them. Super building and I love the eerie green and yellow tones</td>', 'Two people spotted the same scene! I love the glowing bush. The only personal niggle are the green and yellow lights on the left. I think I would have either cropped them out a bit and burned them in or just burned them in. They are the brightest items in the image and I keep getting distracted by them. Super building and I love the eerie green and yellow tones', '2011-09-01 15:30:48.000000', NULL, 1),
(6523467, 969859, 59695, '<td valign="top">How long was this exposure! A nicely executed image</td>', 'How long was this exposure! A nicely executed image', '2011-09-01 15:31:19.000000', NULL, 1),
(6523470, 969887, 59695, '<td valign="top">Wowzers - an eye extravaganza. It''s like an extreme visual hit, but will it have longevity of interst as an image? I guess for the comp that doesn''t matter.</td>', 'Wowzers - an eye extravaganza. It''s like an extreme visual hit, but will it have longevity of interst as an image? I guess for the comp that doesn''t matter.', '2011-09-01 15:36:54.000000', NULL, 1),
(6523471, 969169, 59695, '<td valign="top">Very alienesque image - love the little sun\starburst in the middle</td>', 'Very alienesque image - love the little sun\starburst in the middle', '2011-09-01 15:37:38.000000', NULL, 1),
(6523472, 969892, 59695, '<td valign="top">Two''s company..... I like hte comp of this version and light explosion from the roof. I might have been tempted to burn in the bottom left and the bright grass causes a little bit of a distraction, but that is being picky!</td>', 'Two''s company..... I like hte comp of this version and light explosion from the roof. I might have been tempted to burn in the bottom left and the bright grass causes a little bit of a distraction, but that is being picky!', '2011-09-01 15:39:12.000000', NULL, 1),
(6523474, 969873, 59695, '<td valign="top">This image makes me feel a little queasy as if I am dizzy and falling!<br/>Personally I would have cropped a bit off the right to take the tree off centre as I feel that is a stronger composition. the stones on the left make a great lead in to the image and lead the eye nicely to the tree. Would love to know your thoughts on the crop.</td>', 'This image makes me feel a little queasy as if I am dizzy and falling!Personally I would have cropped a bit off the right to take the tree off centre as I feel that is a stronger composition. the stones on the left make a great lead in to the image and lead the eye nicely to the tree. Would love to know your thoughts on the crop.', '2011-09-01 15:42:31.000000', NULL, 1),
(6523478, 970195, 59695, '<td valign="top">Super model and general pose, interesting idea however, the blurred head doesn''t work for me personally, however I do like the tones and general lighting. Do you have an image with a face?</td>', 'Super model and general pose, interesting idea however, the blurred head doesn''t work for me personally, however I do like the tones and general lighting. Do you have an image with a face?', '2011-09-01 15:44:25.000000', NULL, 1),
(6523482, 969871, 59695, '<td valign="top">Good solid classic image, right time of day to have some colour and interest in the sky</td>', 'Good solid classic image, right time of day to have some colour and interest in the sky', '2011-09-01 15:44:56.000000', NULL, 1),
(6523489, 969813, 59695, '<td valign="top">Very etheral image, the top 20% of the image I find, personally, too bright and distracting and would be tempted to crop it off, with maybe a little from the left too? Thoughts?</td>', 'Very etheral image, the top 20% of the image I find, personally, too bright and distracting and would be tempted to crop it off, with maybe a little from the left too? Thoughts?', '2011-09-01 15:47:02.000000', NULL, 1),
(6523492, 970156, 59695, '<td valign="top">Nicely executed classic image</td>', 'Nicely executed classic image', '2011-09-01 15:47:28.000000', NULL, 1),
(6523499, 970020, 59695, '<td valign="top">Love the textures and tones, enhanced by the b&amp;w approach, but feels an image of two halves fighting each other with the bright top and dark bottom, perhaps a gentle burning in might improve??</td>', 'Love the textures and tones, enhanced by the b&w approach, but feels an image of two halves fighting each other with the bright top and dark bottom, perhaps a gentle burning in might improve??', '2011-09-01 15:49:26.000000', NULL, 1),
(6523502, 969832, 59695, '<td valign="top">Good to see a different pov for light trail scene</td>', 'Good to see a different pov for light trail scene', '2011-09-01 15:49:50.000000', NULL, 1),
(6523505, 969705, 59695, '<td valign="top">Good idea, would have been better, for me, if in a suit\costume to add more drama and mood</td>', 'Good idea, would have been better, for me, if in a suit\costume to add more drama and mood', '2011-09-01 15:50:36.000000', NULL, 1),
(6523508, 969922, 59695, '<td valign="top">Good detail and textures, I like to contrasting b&amp;w approach adds a bit more mood</td>', 'Good detail and textures, I like to contrasting b&w approach adds a bit more mood', '2011-09-01 15:51:39.000000', NULL, 1),
(6523542, 969505, 59695, '<td valign="top">Great shapes and pattern, the top quarter I find personally distracts from the water flow and doesn''t, I feel, contribute to the image so I would be tempted to crop it out. The left hand third, cropped or not is another question, it does add context, but without it, perhaps gives the water with a milky flow more impact - hmm interesting might be worth experimenting and I would love to hear your thoughts</td>', 'Great shapes and pattern, the top quarter I find personally distracts from the water flow and doesn''t, I feel, contribute to the image so I would be tempted to crop it out. The left hand third, cropped or not is another question, it does add context, but without it, perhaps gives the water with a milky flow more impact - hmm interesting might be worth experimenting and I would love to hear your thoughts', '2011-09-01 16:05:28.000000', NULL, 1),
(6523545, 969497, 59695, '<td valign="top">Good strong lead in lines, a lot of negative space on the right, that might benefit from a tighter crop, I appreciate that this there to preserve the right hand leg, but I think the sacrifice of it would serve for a stronger comp - thoughts??</td>', 'Good strong lead in lines, a lot of negative space on the right, that might benefit from a tighter crop, I appreciate that this there to preserve the right hand leg, but I think the sacrifice of it would serve for a stronger comp - thoughts??', '2011-09-01 16:08:56.000000', NULL, 1),
(6523547, 969976, 59695, '<td valign="top">Great colours, fun image, I like the jaunty angle</td>', 'Great colours, fun image, I like the jaunty angle', '2011-09-01 16:09:23.000000', NULL, 1),
(6523548, 970116, 59695, '<td valign="top">Good strong image, I like the lead in on the left and that the sky is not completely black</td>', 'Good strong image, I like the lead in on the left and that the sky is not completely black', '2011-09-01 16:10:13.000000', NULL, 1),
(6523549, 970174, 59695, '<td valign="top">Good POV, an image that wouldn''t look out of place in a motoring magazine</td>', 'Good POV, an image that wouldn''t look out of place in a motoring magazine', '2011-09-01 16:11:07.000000', NULL, 1),
