(6525499, 969884, 136346, '<td valign="top">it''s a little dark in the upper half, but it receives high marks anyway.</td>', 'it''s a little dark in the upper half, but it receives high marks anyway.', '2011-09-02 19:47:38.000000', NULL, 1),
(6525502, 969892, 136346, '<td valign="top">I love the concept, however I am put of by the noise in the sky.  I gave it a high mark, regardless, because of the effort and composition.</td>', 'I love the concept, however I am put of by the noise in the sky.  I gave it a high mark, regardless, because of the effort and composition.', '2011-09-02 19:50:37.000000', NULL, 1),
